text:
{
  "design": {
    "theme": "playground",
    "picture_style": "photo"
  },
  "flow": [
    {
      "slide": 1,
      "does": "Recall familiar animal names",
      "look_at": {
        "kind": "picture",
        "shows": "Four familiar adult animals"
      },
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Introduce the learning goals",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Name the four adult animals",
      "look_at": {
        "kind": "picture",
        "shows": "A cow, sheep, hen and dog"
      },
      "teaches": [1]
    },
    {
      "slide": 4,
      "does": "Model two adult–young matches",
      "look_at": {
        "kind": "picture",
        "shows": "A cow with a calf and a sheep with a lamb"
      },
      "teaches": [1]
    },
    {
      "slide": 5,
      "does": "Check cow and sheep matches",
      "look_at": {
        "kind": "picture",
        "shows": "Separate adults and young in mixed positions"
      },
      "teaches": [1]
    },
    {
      "slide": 6,
      "does": "Model the other two matches",
      "look_at": {
        "kind": "picture",
        "shows": "A hen with chicks and a dog with puppies"
      },
      "teaches": [1]
    },
    {
      "slide": 7,
      "does": "Check hen and dog matches",
      "look_at": {
        "kind": "picture",
        "shows": "Separate hens, dogs, chicks and puppies"
      },
      "teaches": [1]
    },
    {
      "slide": 8,
      "does": "Predict how a chick will change",
      "look_at": {
        "kind": "picture",
        "shows": "A small fluffy chick"
      },
      "teaches": [2]
    },
    {
      "slide": 9,
      "does": "Model chick growth and feather changes",
      "look_at": {
        "kind": "picture-sequence",
        "shows": "A female chick growing into a hen"
      },
      "teaches": [2]
    },
    {
      "slide": 10,
      "does": "Order and describe a similar growth sequence",
      "look_at": {
        "kind": "picture",
        "shows": "Three growth stages in mixed order"
      },
      "teaches": [2]
    },
    {
      "slide": 11,
      "does": "Correct the idea that only size changes",
      "look_at": {
        "kind": "picture",
        "shows": "Close views of chick fluff and adult hen feathers"
      },
      "teaches": [2]
    },
    {
      "slide": 12,
      "does": "Apply growth ideas to a partly grown bird",
      "look_at": {
        "kind": "picture",
        "shows": "A young female chicken with both fluff and developing feathers"
      },
      "teaches": [2]
    }
  ],
  "title": {
    "template": "title",
    "heading": "Animals and their young",
    "lead": "Which animals can you name?",
    "picture": {
      "shows": "Four separate photographs of familiar adult animals",
      "must_see": [
        "adult cow",
        "adult sheep",
        "adult hen",
        "adult dog"
      ],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "Adult animals",
      "lead": "Say each animal’s name.",
      "points": [
        "cow • sheep",
        "hen • dog"
      ],
      "figure": {
        "shows": "Four separate adult animal photographs in reading order: cow, sheep, hen, dog",
        "must_see": [
          "adult cow",
          "adult sheep",
          "adult hen",
          "adult dog"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "compare",
      "heading": "Adults and their young",
      "columns": [
        {
          "label": "cow → calf",
          "text": "A calf is a young cow.",
          "picture": {
            "shows": "An adult cow beside a small calf",
            "must_see": [
              "adult cow",
              "small calf"
            ],
            "subject": "generic"
          }
        },
        {
          "label": "sheep → lamb",
          "text": "A lamb is a young sheep.",
          "picture": {
            "shows": "An adult sheep beside a small lamb",
            "must_see": [
              "adult sheep",
              "small lamb"
            ],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "question-set",
      "heading": "Find the young",
      "questions": [
        "Point to the cow and its young.",
        "Point to the sheep and its young.",
        "Name both young animals."
      ],
      "instruction": "Look and say.",
      "picture": {
        "shows": "Four equally sized separate photo panels: adult cow upper left, lamb upper right, adult sheep lower left, calf lower right; no connecting lines",
        "must_see": [
          "adult cow",
          "small lamb",
          "adult sheep",
          "small calf"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "compare",
      "heading": "More adults and young",
      "columns": [
        {
          "label": "hen → chick",
          "text": "A chick is a young chicken.",
          "picture": {
            "shows": "An adult hen beside a small chick",
            "must_see": [
              "adult hen",
              "small fluffy chick"
            ],
            "subject": "generic"
          }
        },
        {
          "label": "dog → puppy",
          "text": "A puppy is a young dog.",
          "picture": {
            "shows": "An adult dog beside a small puppy",
            "must_see": [
              "adult dog",
              "small puppy"
            ],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "question-set",
      "heading": "Find the young",
      "questions": [
        "Point to the hen and its young.",
        "Point to the dog and its young.",
        "Name both young animals."
      ],
      "instruction": "Look and say.",
      "picture": {
        "shows": "Four equally sized separate photo panels: adult hen upper left, puppy upper right, adult dog lower left, chick lower right; no connecting lines",
        "must_see": [
          "adult hen",
          "small puppy",
          "adult dog",
          "small fluffy chick"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "discussion",
      "heading": "What will change?",
      "lead": "Tell your partner how this chick might change as it grows.",
      "picture": {
        "shows": "A newly hatched female chick standing with its whole body visible",
        "must_see": [
          "small body",
          "soft fluffy covering",
          "short wings"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "picture-sequence",
      "heading": "A chick grows into a hen",
      "sequence": [
        {
          "shows": "A newly hatched female chick, with soft down and no full adult feather covering, photographed at the same scale as the later stages",
          "must_see": [
            "small body",
            "soft fluffy covering",
            "short wings"
          ],
          "subject": "generic",
          "caption": "Small and fluffy"
        },
        {
          "shows": "An older female chick of the same breed, larger with emerging wing feathers and some remaining down, not yet fully adult",
          "must_see": [
            "larger body",
            "growing wing feathers",
            "remaining soft fluff"
          ],
          "subject": "generic",
          "caption": "Bigger; feathers grow"
        },
        {
          "shows": "A fully grown hen of the same breed, larger still and covered with adult feathers",
          "must_see": [
            "large adult body",
            "full feather covering",
            "long tail feathers"
          ],
          "subject": "generic",
          "caption": "Hen with adult feathers"
        }
      ]
    },
    {
      "template": "big-visual",
      "heading": "Put them in order",
      "lead": "Point from youngest to oldest. Say what changes.",
      "figure": {
        "shows": "Three separate photographs of one chicken breed at the same scale, arranged left to right as adult hen, newly hatched female chick, older female chick; no arrows",
        "must_see": [
          "fully feathered hen",
          "small fluffy chick",
          "partly feathered youngster"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "compare",
      "heading": "More than getting bigger",
      "columns": [
        {
          "label": "chick",
          "text": "Soft and fluffy",
          "picture": {
            "shows": "Close view of a newly hatched chick showing its down",
            "must_see": [
              "soft fluffy down",
              "small chick wing"
            ],
            "subject": "generic"
          }
        },
        {
          "label": "hen",
          "text": "Adult feathers",
          "picture": {
            "shows": "Close view of an adult hen showing its wing and body feathers",
            "must_see": [
              "overlapping adult feathers",
              "long wing feathers"
            ],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "discussion",
      "heading": "What happens next?",
      "lead": "This young bird is not fully grown. Tell your partner two ways it will change.",
      "picture": {
        "shows": "A partly grown female chicken with emerging wing feathers and visible remaining down, standing alone",
        "must_see": [
          "partly grown body",
          "developing wing feathers",
          "remaining soft fluff"
        ],
        "subject": "generic"
      }
    }
  ]
}
